12: export function Reveal({ children, delay = 0, className = '', as = 'div', variant = 'up' }: RevealProps) {
13:   const ref = useRef<HTMLElement | null>(null);
14:   const [shown, setShown] = useState(false);
15: 
16:   useEffect(() => {
17:     const node = ref.current;
18:     if (!node) return;
19:     if (typeof IntersectionObserver === 'undefined') {
20:       setShown(true);
21:       return;
22:     }
23:     const observer = new IntersectionObserver(
24:       (entries) => {
25:         entries.forEach((entry) => {
26:           if (entry.isIntersecting) {
27:             setShown(true);
28:             observer.disconnect();
29:           }
30:         });
31:       },
32:       { rootMargin: '0px 0px -8% 0px', threshold: 0.05 },
33:     );
34:     observer.observe(node);
35:     return () => observer.disconnect();
36:   }, []);
37: 
38:   const Tag = as as 'div';
39:   const style = { '--reveal-delay': `${delay}ms` } as CSSProperties;
40: 
41:   return (
42:     <Tag
43:       ref={ref as never}
44:       className={`reveal reveal--${variant} ${shown ? 'is-in' : ''} ${className}`.trim()}
45:       style={style}
46:     >
47:       {children}
48:     </Tag>
49:   );
50: }

