/* ------------------------------------------------------------------
   Pointer tilt for screenshots
------------------------------------------------------------------ */

.tilt {
  --rx: 0deg;
  --ry: 0deg;
  --mx: 50%;
  --my: 50%;
  position: relative;
  border-radius: var(--tilt-r, 22px);
  transform: perspective(1200px) rotateX(var(--rx)) rotateY(var(--ry));
  transition: transform 0.55s var(--ease-out);
  will-change: transform;
}

.tilt.is-tilting {
  transition: transform 0.1s linear;
}

.tilt__inner {
  position: relative;
  border-radius: inherit;
  transition: transform 0.65s var(--ease-spring);
  transform-origin: center;
}

.tilt.is-tilting .tilt__inner {
  transform: scale(1.04);
}

.tilt::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background: radial-gradient(
    360px circle at var(--mx) var(--my),
    rgb(255 255 255 / 0.06),
    transparent 62%
  );
  opacity: 0;
  transition: opacity 0.3s var(--ease-out);
}

.tilt.is-tilting::after {
  opacity: 1;
}

.hero-tilt {
  --tilt-r: 20px;
}

.preview-tilt,
.showcase__tilt {
  --tilt-r: 22px;
}


/* screenshots are pictures, not UI: no selection, no drag, no pointer cursor */
.app-window,
.preview-frame,
.mock {
  user-select: none;
  -webkit-user-select: none;
  cursor: default;
}

.app-window__shot,
.preview-frame__screen img {
  pointer-events: none;
}

/* ------------------------------------------------------------------
   Header
------------------------------------------------------------------ */

.site-header {
---
  opacity: 0.7;
}

.showcase__tilt {
  position: relative;
  z-index: 1;
}

/* ------------------------------------------------------------------
   Features
------------------------------------------------------------------ */

.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.feature {
  display: flex;
  flex-direction: column;
  padding: clamp(22px, 2.4vw, 28px);
  border-radius: var(--r-lg);
  transition: box-shadow var(--dur-3) var(--ease-out);
}

.feature:hover {
  box-shadow: var(--card-shadow-hover);
}

/* cards behave like small photos: tilt and grow under the pointer */
.feature-cell,
.link-cell {
  display: flex;
}

.card-tilt {
  --tilt-r: var(--r-lg);
  display: flex;
  width: 100%;
}

.card-tilt.is-tilting .tilt__inner {
  transform: scale(1.03);
}

.install-tilt {
  --tilt-r: var(--r-xl);
  display: flex;
  width: 100%;
}

.install-tilt.is-tilting .tilt__inner,
.builder-tilt.is-tilting .tilt__inner {
  transform: scale(1.018);
}

.builder-tilt {
  --tilt-r: var(--r-2xl);
  display: flex;
  width: 100%;
}

.feature,
.link-card {
  flex: 1;
}

.feature__icon {
  display: grid;
  place-items: center;

