const tabID = "tab_3270d559-48d2-4dec-b053-da01b34aed2c"
const res = await tools.browser.evaluate({
  tabID,
  script: `(async () => {
    const wait = (ms) => new Promise(r => setTimeout(r, ms));
    const el = document.querySelector('.preview-shell');
    const log = [];
    const io = new IntersectionObserver((entries) => {
      entries.forEach(e => log.push({ t: performance.now(), isInt: e.isIntersecting, ratio: +e.intersectionRatio.toFixed(3) }));
    }, { rootMargin: '0px 0px -8% 0px', threshold: 0.05 });
    io.observe(el);
    await wait(300);
    const before = { cls: el.className, top: Math.round(el.getBoundingClientRect().top), h: Math.round(el.getBoundingClientRect().height), vh: innerHeight };
    document.getElementById('links').scrollIntoView({behavior:'instant', block:'start'});
    await wait(500);
    const after = { cls: el.className, top: Math.round(el.getBoundingClientRect().top) };
    document.getElementById('preview').scrollIntoView({behavior:'instant', block:'start'});
    await wait(800);
    const back = { cls: el.className, top: Math.round(el.getBoundingClientRect().top) };
    io.disconnect();
    return { before, after, back, log };
  })()`
})
return res.value

